import SnackBar from "@/components/SnackBar.vue";
import ContainerList from "@/components/VehicleOptimizer/ContainerList.vue";
import ItemsList from "@/components/VehicleOptimizer/ItemsList.vue";
import AddConatinerDialogue from "@/components/VehicleOptimizer/PopUpsDialogues/AddConatinerDialogue.vue";
import AddItemDialog from "./PopUpsDialogues/AddItemDialog.vue";
export default {
  components: {
    SnackBar,
    ContainerList,
    ItemsList,
    AddConatinerDialogue,
    AddItemDialog
  },
  data() {
    return {
      vehichleItems: "conatainers",
      SnackBarComponent: {},
      addContainerSizes: false,
      componentCheck: 0,
      countCheck: 0,
      addlistItem: false,
      CheckItem: 0,
      cardHeight: 0
    };
  },
  mounted() {
    this.cardHeight = window.innerHeight - 125;
  },
  methods: {
    create_container() {
      this.addContainerSizes = true;
      this.componentCheck = 1;
    },
    create_items() {
      this.componentCheck = 2;
      this.addlistItem = true;
    },
    success_msg(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addContainerSizes = false;
      this.countCheck += 1;
    },
    successitemmsg(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addlistItem = false;
      this.CheckItem += 1;
    },
    error_msg(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    }
  }
};
